'use strict';

// Cron schedules for the job runner.
//
// A schedule is the usual five fields, minute hour day-of-month month
// day-of-week, separated by spaces. The runner hands us the timestamp it is
// asking about as 'YYYY-MM-DDTHH:MM'.

const FIELDS = [
  { key: 'minute', label: 'minute', min: 0, max: 59 },
  { key: 'hour', label: 'hour', min: 0, max: 23 },
  { key: 'dayOfMonth', label: 'day-of-month', min: 1, max: 31 },
  { key: 'month', label: 'month', min: 1, max: 12 },
  { key: 'dayOfWeek', label: 'day-of-week', min: 0, max: 6 },
];

// One field of the expression, expanded into the values it selects.
function parseField(spec, field) {
  const text = String(spec === undefined || spec === null ? '' : spec).trim();
  if (text === '*') {
    const all = [];
    for (let value = field.min; value <= field.max; value += 1) {
      all.push(value);
    }
    return all;
  }
  const values = [];
  for (const part of text.split(',')) {
    const value = Number(part.trim());
    if (Number.isInteger(value)) {
      values.push(value);
    }
  }
  return values.sort((a, b) => a - b);
}

function parseCron(expr) {
  const parts = String(expr === undefined || expr === null ? '' : expr).trim().split(/\s+/);
  const cron = {};
  FIELDS.forEach((field, i) => {
    cron[field.key] = parseField(parts[i], field);
  });
  return cron;
}

// True when the schedule selects the minute the runner is asking about.
function matches(expr, when) {
  const cron = parseCron(expr);
  const at = when === undefined || when === null ? new Date() : new Date(when);
  return (
    cron.minute.indexOf(at.getMinutes()) >= 0 &&
    cron.hour.indexOf(at.getHours()) >= 0 &&
    cron.dayOfMonth.indexOf(at.getDate()) >= 0 &&
    cron.month.indexOf(at.getMonth() + 1) >= 0 &&
    cron.dayOfWeek.indexOf(at.getDay()) >= 0
  );
}

module.exports = { parseCron, matches };

