'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseCron, matches, nextFire, fireCountByMonth } = require('./src/cron.js');
const { planRuns } = require('./src/scheduler.js');

const upto = (min, max) => {
  const out = [];
  for (let v = min; v <= max; v += 1) out.push(v);
  return out;
};
const ALL_MINUTES = upto(0, 59);
const ALL_HOURS = upto(0, 23);
const ALL_DOM = upto(1, 31);
const ALL_MONTHS = upto(1, 12);
const ALL_DOW = upto(0, 6);

test('s1 a range selects every value between its two ends, lists included', () => {
  const office = parseCron('0 9-17 * * 1-5');
  assert.deepStrictEqual(office.hour, [9, 10, 11, 12, 13, 14, 15, 16, 17]);
  assert.deepStrictEqual(office.dayOfWeek, [1, 2, 3, 4, 5]);
  assert.deepStrictEqual(office.minute, [0]);
  assert.deepStrictEqual(office.dayOfMonth, ALL_DOM, 'a bare star is still every value in the field');
  assert.deepStrictEqual(office.month, ALL_MONTHS);

  const mixed = parseCron('1,3-5,9 * 28-31 6-8 *');
  assert.deepStrictEqual(mixed.minute, [1, 3, 4, 5, 9], 'a range inside a list is still a range');
  assert.deepStrictEqual(mixed.dayOfMonth, [28, 29, 30, 31]);
  assert.deepStrictEqual(mixed.month, [6, 7, 8]);
  assert.deepStrictEqual(mixed.dayOfWeek, ALL_DOW);

  assert.deepStrictEqual(parseCron('5-5 * * * *').minute, [5], 'a range of one value is that value');
  assert.deepStrictEqual(parseCron('0 0-23 * * *').hour, ALL_HOURS);
  assert.deepStrictEqual(parseCron('5,5,1-3,2 * * * *').minute, [1, 2, 3, 5], 'ascending, with no repeats');
});

test('s2 a step walks its range in strides', () => {
  assert.deepStrictEqual(parseCron('*/15 * * * *').minute, [0, 15, 30, 45]);
  assert.deepStrictEqual(parseCron('0 */6 * * *').hour, [0, 6, 12, 18]);
  assert.deepStrictEqual(parseCron('10-40/10 * * * *').minute, [10, 20, 30, 40]);
  assert.deepStrictEqual(parseCron('10-41/10 * * * *').minute, [10, 20, 30, 40], 'the stride stops inside the range');
  assert.deepStrictEqual(parseCron('45/10 * * * *').minute, [45, 55], 'a bare start runs on to the top of the field');
  assert.deepStrictEqual(parseCron('0 5/4 * * *').hour, [5, 9, 13, 17, 21]);
  assert.deepStrictEqual(parseCron('*/1 * * * *').minute, ALL_MINUTES);
  assert.deepStrictEqual(parseCron('0,*/20 * * * *').minute, [0, 20, 40], 'a step inside a list still merges');
  assert.deepStrictEqual(parseCron('0 0 */10 * *').dayOfMonth, [1, 11, 21, 31], 'day-of-month starts at 1, not at 0');
  assert.deepStrictEqual(parseCron('0 0 * */3 *').month, [1, 4, 7, 10]);
  assert.deepStrictEqual(parseCron('0 0 * * */2').dayOfWeek, [0, 2, 4, 6]);
});

test('s3 a schedule that cannot be honoured is refused, and the message names the field', () => {
  assert.throws(() => parseCron('* * * *'), /five/i, 'four fields is not a schedule');
  assert.throws(() => parseCron('* * * * * *'), /five/i, 'six fields is not a schedule either');
  assert.throws(() => parseCron(''), /five/i);
  assert.throws(() => parseCron('60 * * * *'), /minute/i);
  assert.throws(() => parseCron('* 24 * * *'), /hour/i);
  assert.throws(() => parseCron('* * 0 * *'), /day-of-month/i);
  assert.throws(() => parseCron('* * 32 * *'), /day-of-month/i);
  assert.throws(() => parseCron('* * * 0 *'), /month/i);
  assert.throws(() => parseCron('* * * 13 *'), /month/i);
  assert.throws(() => parseCron('* * * * 9'), /day-of-week/i);
  assert.throws(() => parseCron('* * * * -1'), /day-of-week/i);
  assert.throws(() => parseCron('30-10 * * * *'), /minute/i, 'a range that runs backwards is refused');
  assert.throws(() => parseCron('* 20-4 * * *'), /hour/i);
  assert.throws(() => parseCron('*/0 * * * *'), /minute/i, 'a step of zero never advances');
  assert.throws(() => parseCron('*/-2 * * * *'), /minute/i);
  assert.throws(() => parseCron('*/2.5 * * * *'), /minute/i);
  assert.throws(() => parseCron('x * * * *'), /minute/i);
  assert.throws(() => parseCron('* * * banana *'), /month/i);
  assert.throws(() => parseCron('* * 1,,3 * *'), /day-of-month/i);

  assert.doesNotThrow(() => parseCron('0 0 31 12 *'), 'the edges of every field are still legal');
  assert.doesNotThrow(() => parseCron('59 23 1 1 0'));
  assert.doesNotThrow(() => parseCron('  0   9   *   *   1  '), 'stray whitespace between fields is fine');
});

test('s4 matches reads the timestamp it is handed and never the machine clock', () => {
  assert.strictEqual(matches('30 9 * * *', '2026-03-10T09:30'), true);
  assert.strictEqual(matches('30 9 * * *', '2026-03-10T09:31'), false);
  assert.strictEqual(matches('30 9 * * *', '2026-03-10T08:30'), false);
  assert.strictEqual(matches('*/15 * * * *', '2026-03-10T09:45'), true);
  assert.strictEqual(matches('*/15 * * * *', '2026-03-10T09:46'), false);
  assert.strictEqual(matches('0 0 1 1 *', '2027-01-01T00:00'), true);
  assert.strictEqual(matches('0 0 1 1 *', '2027-01-02T00:00'), false);
  assert.strictEqual(matches('0 12 * * *', '2026-03-10T12:00:45'), true, 'seconds are below the resolution of a schedule');
  assert.strictEqual(matches('0 12 * * *', '2026-03-10T12:00Z'), true, 'a trailing Z is tolerated');
  assert.strictEqual(matches('0 12 * * *', '2026-03-10T12:00:45Z'), true);

  const unreadable = [undefined, null, '', 'now', 'tomorrow', '2026-03-10', '10/03/2026 12:00', '2026-02-30T12:00', '2026-03-10T24:00', '2026-03-10T12:60', 42, {}, new Date()];
  for (const junk of unreadable) {
    assert.throws(
      () => matches('0 12 * * *', junk),
      'an unreadable timestamp is refused rather than quietly replaced by the machine clock'
    );
  }
});

test('s5 nextFire finds the next minute the schedule selects, rolling over as it goes', () => {
  assert.strictEqual(nextFire('*/15 * * * *', '2026-03-10T09:07'), '2026-03-10T09:15');
  assert.strictEqual(nextFire('0 * * * *', '2026-03-10T09:00'), '2026-03-10T10:00', 'strictly after the instant it was given');
  assert.strictEqual(nextFire('5 * * * *', '2026-03-10T09:30'), '2026-03-10T10:05', 'over the hour');
  assert.strictEqual(nextFire('30 2 * * *', '2026-03-10T09:00'), '2026-03-11T02:30', 'over the day');
  assert.strictEqual(nextFire('0 0 1 * *', '2026-03-10T09:00'), '2026-04-01T00:00', 'over the month');
  assert.strictEqual(nextFire('0 0 1 1 *', '2026-03-10T09:00'), '2027-01-01T00:00', 'over the year');
  assert.strictEqual(nextFire('59 23 31 12 *', '2026-12-31T23:58'), '2026-12-31T23:59');
  assert.strictEqual(nextFire('0 12 29 2 *', '2026-03-01T00:00'), '2028-02-29T12:00', '2027 has no 29th of February');
  assert.strictEqual(nextFire('0 12 29 2 *', '2028-02-29T12:00'), '2032-02-29T12:00');
  assert.strictEqual(nextFire('0 0 30 2 *', '2026-03-10T09:00'), null, 'the 30th of February never comes round');
  assert.strictEqual(nextFire('0 0 31 4 *', '2026-03-10T09:00'), null, 'April has no 31st');
  assert.throws(() => nextFire('*/15 * * * *', 'soon'));
  assert.throws(() => nextFire('*/15 * * *', '2026-03-10T09:07'), /five/i);
});

test('s6 planRuns puts the whole job table in order without one bad row taking it down', () => {
  const jobs = [
    { id: 'nightly', cron: '0 3 * * *' },
    { id: 'quarter', cron: '*/15 * * * *' },
    { id: 'paused', cron: '*/5 * * * *', enabled: false },
    { id: 'never', cron: '0 0 30 2 *' },
    { id: 'broken', cron: '0 3 * *' },
    { id: 'alpha', cron: '*/15 * * * *' },
    { id: 'live', cron: '0 3 * * *', enabled: true },
    { id: 'dead', cron: '0 0 31 4 *' },
    { id: 'aground', cron: '61 * * * *' },
  ];
  const plan = planRuns(jobs, '2026-03-10T09:07');
  assert.deepStrictEqual(
    plan.map((entry) => entry.id),
    ['alpha', 'quarter', 'live', 'nightly', 'dead', 'never', 'aground', 'broken'],
    'soonest first, ties by id, then the ones that never fire in id order, then the unparseable in id order'
  );
  assert.deepStrictEqual(plan[0], { id: 'alpha', at: '2026-03-10T09:15' });
  assert.deepStrictEqual(plan[1], { id: 'quarter', at: '2026-03-10T09:15' });
  assert.deepStrictEqual(plan[2], { id: 'live', at: '2026-03-11T03:00' });
  assert.deepStrictEqual(plan[3], { id: 'nightly', at: '2026-03-11T03:00' });
  assert.deepStrictEqual(plan[4], { id: 'dead', at: null });
  assert.deepStrictEqual(plan[5], { id: 'never', at: null });
  for (const entry of [plan[6], plan[7]]) {
    assert.ok(typeof entry.error === 'string' && entry.error.length > 0, 'the parse failure comes back as text');
    assert.ok(!('at' in entry), 'a row that will not parse has no fire time to report');
  }
  assert.ok(plan.every((entry) => entry.id !== 'paused'), 'a disabled job is not in the plan at all');

  assert.deepStrictEqual(planRuns([], '2026-03-10T09:07'), []);
  assert.deepStrictEqual(planRuns(undefined, '2026-03-10T09:07'), []);
});

test('s7 day-of-month and day-of-week are an or, and only a bare star is unrestricted', () => {
  // Both restricted: the 1st of any month, or any Monday.
  assert.strictEqual(matches('0 0 1 * 1', '2026-03-09T00:00'), true, 'a Monday that is not the 1st');
  assert.strictEqual(matches('0 0 1 * 1', '2026-03-01T00:00'), true, 'the 1st, on a Sunday');
  assert.strictEqual(matches('0 0 1 * 1', '2026-03-10T00:00'), false, 'neither the 1st nor a Monday');

  // Only day-of-month restricted.
  assert.strictEqual(matches('0 0 15 * *', '2026-03-15T00:00'), true);
  assert.strictEqual(matches('0 0 15 * *', '2026-03-16T00:00'), false);

  // Only day-of-week restricted.
  assert.strictEqual(matches('0 0 * * 1', '2026-03-09T00:00'), true);
  assert.strictEqual(matches('0 0 * * 1', '2026-03-10T00:00'), false, 'an unrestricted day-of-month does not widen this');

  // Neither restricted.
  assert.strictEqual(matches('0 0 * * *', '2026-03-10T00:00'), true);

  // A field written as anything other than a bare star counts as restricted.
  assert.strictEqual(matches('0 0 13 * */2', '2026-03-10T00:00'), true, 'a Tuesday, and */2 is a restriction');
  assert.strictEqual(matches('0 0 13 * */2', '2026-03-13T00:00'), true, 'the 13th');
  assert.strictEqual(matches('0 0 13 * */2', '2026-03-09T00:00'), false, 'a Monday that is not the 13th');
  assert.strictEqual(matches('0 0 */5 * 1', '2026-03-11T00:00'), true, 'the 11th, and */5 is a restriction');
  assert.strictEqual(matches('0 0 */5 * 1', '2026-03-09T00:00'), true, 'a Monday');
  assert.strictEqual(matches('0 0 */5 * 1', '2026-03-10T00:00'), false);
  assert.strictEqual(matches('0 0 15 * 0-6', '2026-03-10T00:00'), true, '0-6 is a restriction, not a star');

  assert.strictEqual(nextFire('0 0 1 * 1', '2026-03-02T00:00'), '2026-03-09T00:00');
  assert.strictEqual(nextFire('0 0 1 * 1', '2026-03-30T12:00'), '2026-04-01T00:00');
  assert.strictEqual(nextFire('0 0 * * 1', '2026-03-02T00:00'), '2026-03-09T00:00');
  assert.strictEqual(nextFire('0 0 15 * *', '2026-03-15T00:00'), '2026-04-15T00:00');
});

test('s8 names, seven as Sunday, and the shorthands', () => {
  assert.deepStrictEqual(parseCron('0 0 * JAN,MAR,DEC *').month, [1, 3, 12]);
  assert.deepStrictEqual(parseCron('0 0 * jun-aug *').month, [6, 7, 8]);
  assert.deepStrictEqual(parseCron('0 0 * Feb *').month, [2]);
  assert.deepStrictEqual(parseCron('0 0 * * MON-FRI').dayOfWeek, [1, 2, 3, 4, 5]);
  assert.deepStrictEqual(parseCron('0 0 * * mon-fri/2').dayOfWeek, [1, 3, 5]);
  assert.deepStrictEqual(parseCron('0 0 * * sat,sun').dayOfWeek, [0, 6]);
  assert.deepStrictEqual(parseCron('0 0 * * 7').dayOfWeek, [0], 'seven is a second spelling of Sunday');
  assert.deepStrictEqual(parseCron('0 0 * * 5-7').dayOfWeek, [0, 5, 6]);
  assert.deepStrictEqual(parseCron('0 0 * * 0-7').dayOfWeek, ALL_DOW);
  assert.deepStrictEqual(parseCron('0 0 * * 0,7').dayOfWeek, [0]);
  assert.throws(() => parseCron('0 0 * * MON-JAN'), /day-of-week/i, 'a month name is not a day name');
  assert.throws(() => parseCron('0 0 * FRI *'), /month/i, 'a day name is not a month name');

  const hourly = parseCron('@hourly');
  assert.deepStrictEqual(hourly.minute, [0]);
  assert.deepStrictEqual(hourly.hour, ALL_HOURS);
  assert.strictEqual(nextFire('@hourly', '2026-03-10T09:07'), '2026-03-10T10:00');
  assert.strictEqual(nextFire('@daily', '2026-03-10T09:07'), '2026-03-11T00:00');
  assert.strictEqual(nextFire('@midnight', '2026-03-10T09:07'), '2026-03-11T00:00');
  assert.strictEqual(nextFire('@weekly', '2026-03-10T09:07'), '2026-03-15T00:00', 'the next Sunday');
  assert.strictEqual(nextFire('@monthly', '2026-03-10T09:07'), '2026-04-01T00:00');
  assert.strictEqual(nextFire('@yearly', '2026-03-10T09:07'), '2027-01-01T00:00');
  assert.strictEqual(nextFire('@annually', '2026-03-10T09:07'), '2027-01-01T00:00');
  assert.strictEqual(matches('@DAILY', '2026-03-10T00:00'), true, 'the shorthands do not care about case');
  assert.throws(() => parseCron('@fortnightly'));
  assert.throws(() => parseCron('@'));
});

test('s9 the last day of the month, and counting back from it', () => {
  assert.strictEqual(matches('0 0 L * *', '2026-03-31T00:00'), true);
  assert.strictEqual(matches('0 0 L * *', '2026-03-30T00:00'), false);
  assert.strictEqual(matches('0 0 L * *', '2026-04-30T00:00'), true, 'April ends on the 30th');
  assert.strictEqual(matches('0 0 l * *', '2026-04-30T00:00'), true, 'lower case reads the same');
  assert.strictEqual(matches('0 0 L * *', '2026-02-28T00:00'), true, 'February in a common year');
  assert.strictEqual(matches('0 0 L * *', '2028-02-29T00:00'), true, 'February in a leap year');
  assert.strictEqual(matches('0 0 L * *', '2028-02-28T00:00'), false, 'the 28th is not the last day of a leap February');

  assert.strictEqual(matches('0 0 L-1 * *', '2026-03-30T00:00'), true);
  assert.strictEqual(matches('0 0 L-1 * *', '2026-03-31T00:00'), false);
  assert.strictEqual(matches('0 0 L-3 * *', '2026-06-27T00:00'), true, 'June ends on the 30th');
  assert.strictEqual(matches('0 0 L-3 * *', '2026-02-25T00:00'), true, 'a short February counts back from the 28th');
  assert.strictEqual(matches('0 0 L-0 * *', '2026-03-31T00:00'), true);

  assert.strictEqual(matches('0 0 15,L * *', '2026-03-15T00:00'), true);
  assert.strictEqual(matches('0 0 15,L * *', '2026-03-31T00:00'), true);
  assert.strictEqual(matches('0 0 15,L * *', '2026-03-20T00:00'), false);

  assert.strictEqual(nextFire('30 23 L * *', '2026-01-05T00:00'), '2026-01-31T23:30');
  assert.strictEqual(nextFire('30 23 L * *', '2026-01-31T23:30'), '2026-02-28T23:30');
  assert.strictEqual(nextFire('0 0 L 2 *', '2027-03-01T00:00'), '2028-02-29T00:00');
  assert.strictEqual(nextFire('0 0 L-30 * *', '2026-01-01T00:00'), '2026-03-01T00:00', 'February is too short to reach back 30 days');

  // L leaves day-of-month restricted, so the or rule still applies.
  assert.strictEqual(matches('0 0 L * 5', '2026-03-06T00:00'), true, 'a Friday that is not the last day');
  assert.strictEqual(matches('0 0 L * 5', '2026-03-31T00:00'), true, 'the last day, on a Tuesday');
  assert.strictEqual(matches('0 0 L * 5', '2026-03-10T00:00'), false);
});

test('s10 the nth weekday of a month, and the last one', () => {
  assert.strictEqual(matches('0 9 * * 5#2', '2026-03-13T09:00'), true, 'the second Friday of March 2026');
  assert.strictEqual(matches('0 9 * * 5#2', '2026-03-06T09:00'), false, 'the first Friday');
  assert.strictEqual(matches('0 9 * * 5#2', '2026-03-20T09:00'), false, 'the third Friday');
  assert.strictEqual(matches('0 9 * * 5#2', '2026-03-12T09:00'), false, 'the Thursday before it');
  assert.strictEqual(matches('0 9 * * FRI#2', '2026-03-13T09:00'), true, 'names work here too');
  assert.strictEqual(matches('0 9 * * 1#1', '2026-03-02T09:00'), true, 'the first Monday of March 2026');
  assert.strictEqual(matches('0 9 * * 1#1', '2026-03-09T09:00'), false);

  assert.strictEqual(matches('0 9 * * 5L', '2026-03-27T09:00'), true, 'the last Friday of March 2026');
  assert.strictEqual(matches('0 9 * * 5L', '2026-03-20T09:00'), false, 'the Friday before the last one');
  assert.strictEqual(matches('0 9 * * 7L', '2026-03-29T09:00'), true, 'the last Sunday, spelled with a seven');
  assert.strictEqual(matches('0 9 * * 7L', '2026-03-22T09:00'), false);
  assert.strictEqual(matches('0 9 * * friL', '2026-03-27T09:00'), true);

  assert.strictEqual(nextFire('0 9 * * 5L', '2026-03-01T00:00'), '2026-03-27T09:00');
  assert.strictEqual(nextFire('0 9 * * 5#5', '2026-03-01T00:00'), '2026-05-29T09:00', 'neither March nor April 2026 has a fifth Friday');
  assert.strictEqual(nextFire('0 9 * * 1#1,5L', '2026-03-03T00:00'), '2026-03-27T09:00');

  assert.strictEqual(matches('0 9 * * 1#1,5L', '2026-03-02T09:00'), true);
  assert.strictEqual(matches('0 9 * * 1#1,5L', '2026-03-27T09:00'), true);
  assert.strictEqual(matches('0 9 * * 1#1,5L', '2026-03-09T09:00'), false);

  // Both of these leave day-of-week restricted, so the or rule still applies.
  assert.strictEqual(matches('0 9 1 * 5#2', '2026-03-01T09:00'), true, 'the 1st, on a Sunday');
  assert.strictEqual(matches('0 9 1 * 5#2', '2026-03-13T09:00'), true, 'the second Friday');
  assert.strictEqual(matches('0 9 1 * 5#2', '2026-03-10T09:00'), false);

  assert.throws(() => parseCron('0 9 * * 5#6'), /day-of-week/i, 'no month has a sixth Friday');
  assert.throws(() => parseCron('0 9 * * 5#0'), /day-of-week/i);
  assert.throws(() => parseCron('0 9 * * 9L'), /day-of-week/i);
});

test('s11 the schedule is written on the operator wall clock, not on UTC', () => {
  const west = { utcOffset: -300 };
  assert.strictEqual(matches('0 3 * * *', '2026-03-10T08:00', west), true, '03:00 five hours behind UTC');
  assert.strictEqual(matches('0 3 * * *', '2026-03-10T03:00', west), false);
  assert.strictEqual(nextFire('0 3 * * *', '2026-03-10T09:00', west), '2026-03-11T08:00');
  assert.strictEqual(matches('0 19 9 * *', '2026-03-10T00:00', west), true, 'still the 9th where the operator is');
  assert.strictEqual(matches('0 19 10 * *', '2026-03-10T00:00', west), false);
  assert.strictEqual(matches('0 0 L * *', '2026-03-31T05:00', west), true, 'the last day of the month, locally');
  assert.strictEqual(matches('0 0 L * *', '2026-04-01T05:00', west), false);

  assert.strictEqual(matches('30 0 * * *', '2026-03-09T19:00', { utcOffset: 330 }), true, 'half hour offsets are real offsets');
  assert.strictEqual(nextFire('0 0 1 * *', '2026-03-31T20:00', { utcOffset: 300 }), '2026-04-30T19:00', 'the local month had already turned over');

  for (const junk of [900, -900, 1.5, '300', null, NaN, true, Infinity]) {
    assert.strictEqual(matches('0 3 * * *', '2026-03-10T03:00', { utcOffset: junk }), true, 'an unusable offset falls back to UTC');
  }
  assert.strictEqual(matches('0 3 * * *', '2026-03-10T03:00', {}), true);
  assert.strictEqual(matches('0 3 * * *', '2026-03-10T03:00'), true);
  assert.strictEqual(nextFire('0 3 * * *', '2026-03-10T09:00'), '2026-03-11T03:00');

  assert.deepStrictEqual(
    planRuns([{ id: 'a', cron: '0 3 * * *' }], '2026-03-10T09:00', west),
    [{ id: 'a', at: '2026-03-11T08:00' }],
    'the plan is drawn on the same wall clock'
  );
});

test('s12 fireCountByMonth counts the fires in a window, month by month', () => {
  assert.deepStrictEqual(
    fireCountByMonth('0 0 * * *', '2026-01-30T00:00', '2026-02-02T00:00'),
    { '2026-01': 1, '2026-02': 2 },
    'open at the start, closed at the end'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 0 * * *', '2026-12-30T00:00', '2027-01-02T00:00'),
    { '2026-12': 1, '2027-01': 2 },
    'over a year boundary'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 12 29 2 *', '2026-01-01T00:00', '2029-01-01T00:00'),
    { '2028-02': 1 },
    'only the leap February in the window'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 0 L 2 *', '2027-01-01T00:00', '2029-01-01T00:00'),
    { '2027-02': 1, '2028-02': 1 }
  );
  assert.deepStrictEqual(fireCountByMonth('*/30 * * * *', '2026-03-10T00:00', '2026-03-10T02:00'), { '2026-03': 4 });

  const wholeYear = fireCountByMonth('0 0 1 * *', '2025-12-31T23:59', '2026-12-31T23:59');
  assert.deepStrictEqual(Object.keys(wholeYear).sort(), [
    '2026-01', '2026-02', '2026-03', '2026-04', '2026-05', '2026-06',
    '2026-07', '2026-08', '2026-09', '2026-10', '2026-11', '2026-12',
  ]);
  assert.ok(Object.keys(wholeYear).every((key) => wholeYear[key] === 1));

  assert.deepStrictEqual(fireCountByMonth('0 0 30 2 *', '2026-01-01T00:00', '2029-01-01T00:00'), {}, 'a schedule that never fires counts nothing');
  assert.deepStrictEqual(fireCountByMonth('0 0 * * *', '2026-03-10T00:00', '2026-03-10T00:00'), {}, 'an empty window');
  assert.strictEqual(fireCountByMonth('0 0 * * *', '2026-03-10T00:00', '2026-03-09T00:00'), null, 'a window that runs backwards');
  assert.strictEqual(fireCountByMonth('0 0 * * *', 'whenever', '2026-03-11T00:00'), null);
  assert.strictEqual(fireCountByMonth('0 0 * * *', '2026-03-10T00:00', '2026-13-01T00:00'), null);
  assert.throws(() => fireCountByMonth('0 0 * *', '2026-03-10T00:00', '2026-03-11T00:00'), /five/i);

  // The month a fire is counted into is the month it lands in locally. The
  // hour field is a bare star in the next four, so the very same instants fire
  // whatever the offset is and the only thing that can differ is the key the
  // count lands under.
  assert.deepStrictEqual(
    fireCountByMonth('0 * * * *', '2026-02-28T21:00', '2026-02-28T23:00', { utcOffset: 300 }),
    { '2026-03': 2 },
    'five hours east of UTC those two fires have already landed in March'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 * * * *', '2026-02-28T21:00', '2026-02-28T23:00'),
    { '2026-02': 2 },
    'and on UTC the very same two fires are February'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 * * * *', '2026-03-01T01:00', '2026-03-01T03:00', { utcOffset: -300 }),
    { '2026-02': 2 },
    'five hours west of UTC those two fires are still February'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 * * * *', '2026-03-01T01:00', '2026-03-01T03:00'),
    { '2026-03': 2 },
    'and on UTC the very same two fires are March'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 0 1 * *', '2026-02-01T00:00', '2026-03-31T00:00', { utcOffset: 300 }),
    { '2026-03': 1 },
    'local midnight on the 1st of March is still February in UTC'
  );
  assert.deepStrictEqual(
    fireCountByMonth('0 0 1 * *', '2026-02-01T00:00', '2026-03-31T00:00'),
    { '2026-03': 1 },
    'and with no offset it is the UTC month'
  );
});

