'use strict';

const { matches, nextFire } = require('./cron.js');

// The job table the runner polls. A job is { id, cron, enabled }, and a job
// with no enabled flag counts as on.
function dueJobs(jobs, when) {
  return (jobs || []).filter((job) => job && job.enabled !== false && matches(job.cron, when));
}

// The next run for every enabled job, soonest first. A job whose expression
// will not parse is reported rather than thrown, because one bad row in the
// table must not take the whole plan down with it.
function planRuns(jobs, from, options) {
  const list = Array.isArray(jobs) ? jobs : [];
  const plan = [];
  for (const job of list) {
    if (!job || job.enabled === false) continue;
    try {
      plan.push({ id: job.id, at: nextFire(job.cron, from, options) });
    } catch (err) {
      plan.push({ id: job.id, error: err.message });
    }
  }
  const rank = (entry) => {
    if (entry.error !== undefined) return 2;
    return entry.at === null ? 1 : 0;
  };
  plan.sort((a, b) => {
    const ra = rank(a);
    const rb = rank(b);
    if (ra !== rb) return ra - rb;
    if (ra === 0 && a.at !== b.at) return a.at < b.at ? -1 : 1;
    const ida = String(a.id);
    const idb = String(b.id);
    if (ida === idb) return 0;
    return ida < idb ? -1 : 1;
  });
  return plan;
}

module.exports = { dueJobs, planRuns };
